// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("POST "+options.BaseURL+"/api/auth/forgot-password", wrapper.ForgotPassword)
	m.HandleFunc("POST "+options.BaseURL+"/api/auth/login", wrapper.Login)
	m.HandleFunc("POST "+options.BaseURL+"/api/auth/logout", wrapper.Logout)
	m.HandleFunc("GET "+options.BaseURL+"/api/auth/me", wrapper.CurrentUser)
	m.HandleFunc("PUT "+options.BaseURL+"/api/auth/password", wrapper.ChangePassword)
	m.HandleFunc("POST "+options.BaseURL+"/api/auth/register", wrapper.Register)
	m.HandleFunc("POST "+options.BaseURL+"/api/auth/reset-password", wrapper.ResetPassword)
	m.HandleFunc("GET "+options.BaseURL+"/api/health", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/api/me/drafts/{slug}", wrapper.GetDraft)
	m.HandleFunc("PUT "+options.BaseURL+"/api/me/drafts/{slug}", wrapper.SaveDraft)
	m.HandleFunc("GET "+options.BaseURL+"/api/me/problems", wrapper.ListSavedProblems)
	m.HandleFunc("PATCH "+options.BaseURL+"/api/me/problems/{slug}", wrapper.SaveProblemState)
	m.HandleFunc("GET "+options.BaseURL+"/api/problems", wrapper.ListProblems)
	m.HandleFunc("POST "+options.BaseURL+"/api/problems", wrapper.CreateProblem)
	m.HandleFunc("POST "+options.BaseURL+"/api/problems/generate", wrapper.GenerateProblem)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/problems/{slug}", wrapper.DeleteProblem)
	m.HandleFunc("GET "+options.BaseURL+"/api/problems/{slug}", wrapper.GetProblem)
	m.HandleFunc("PUT "+options.BaseURL+"/api/problems/{slug}", wrapper.UpdateProblem)
	m.HandleFunc("GET "+options.BaseURL+"/api/problems/{slug}/languages", wrapper.ListProblemLanguages)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/problems/{slug}/languages/{language}", wrapper.DeleteProblemLanguage)
	m.HandleFunc("GET "+options.BaseURL+"/api/problems/{slug}/workspace", wrapper.GetWorkspace)
	m.HandleFunc("POST "+options.BaseURL+"/api/runs", wrapper.CreateRun)
	m.HandleFunc("GET "+options.BaseURL+"/api/runs/{id}", wrapper.GetRun)
	m.HandleFunc("GET "+options.BaseURL+"/api/submissions", wrapper.ListSubmissions)
	m.HandleFunc("POST "+options.BaseURL+"/api/submissions", wrapper.CreateSubmission)
	m.HandleFunc("GET "+options.BaseURL+"/api/submissions/{id}", wrapper.GetSubmission)

	return m
}

